package main

import (
	"context"
	"crypto/sha256"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"os"
	"sync/atomic"
	"testing"
	"time"

	"github.com/stretchr/testify/require"

	"github.com/kubebao/openbao-operator/internal/platform/constants"
	"github.com/kubebao/openbao-operator/internal/port/blobstore"
	portopenbao "github.com/kubebao/openbao-operator/internal/port/openbao"
	backupconfig "github.com/kubebao/openbao-operator/internal/service/backup"
)

// TestExecuteRestoreLargeSnapshotTransport exercises real disk staging and HTTP
// streaming above the old limit. The generated bytes are not an OpenBao snapshot;
// native snapshot application is covered by the restore E2E cases.
func TestExecuteRestoreLargeSnapshotTransport(t *testing.T) {
	if os.Getenv("OPENBAO_TEST_LARGE_RESTORE") != "true" {
		t.Skip("set OPENBAO_TEST_LARGE_RESTORE=true with at least 13 GiB free scratch space")
	}
	const size = constants.DefaultRestoreSnapshotLimitBytes + 1
	hash := sha256.New()
	_, err := io.Copy(hash, io.LimitReader(restoreZeroReader{}, size))
	require.NoError(t, err)
	digest := fmt.Sprintf("sha256:%x", hash.Sum(nil))
	type received struct {
		size   int64
		digest string
		err    error
	}
	result := make(chan received, 1)
	var requests atomic.Int32
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		requests.Add(1)
		if r.Method != http.MethodPost || r.URL.Path != testBackupForceRestorePath {
			http.Error(w, "unexpected request", http.StatusBadRequest)
			return
		}
		bodyHash := sha256.New()
		n, copyErr := io.Copy(bodyHash, r.Body)
		result <- received{n, fmt.Sprintf("sha256:%x", bodyHash.Sum(nil)), copyErr}
		w.WriteHeader(http.StatusNoContent)
	}))
	defer server.Close()
	store := &restoreFlowStore{backupFlowBlobStore: backupFlowBlobStore{
		useHeadResult: true, headResult: &blobstore.ObjectInfo{Size: size},
	}, reader: io.NopCloser(io.LimitReader(restoreZeroReader{}, size))}
	dir := t.TempDir()
	settings := restoreSettings{key: "large-snapshot", force: true, maxSnapshotSizeBytes: 16 * 1024 * 1024 * 1024,
		beforeSubmit: func(_ context.Context, _ portopenbao.ClusterActions, gotDigest string, gotSize int64) error {
			require.Equal(t, digest, gotDigest)
			require.Equal(t, size, gotSize)
			return nil
		},
	}
	ctx, cancel := context.WithTimeout(t.Context(), 10*time.Minute)
	defer cancel()
	require.NoError(t, executeRestore(ctx, ctx, store, settings, dir,
		func(context.Context) (portopenbao.ClusterActions, func(), error) {
			return openClusterClient(&backupconfig.ExecutorConfig{}, "restore", server.URL, "test-token")
		}))
	got := <-result
	require.NoError(t, got.err)
	require.Equal(t, size, got.size)
	require.Equal(t, digest, got.digest)
	require.Equal(t, int32(1), requests.Load())
	require.Equal(t, 1, store.downloads)
	assertRestoreScratchEmpty(t, dir)
}

type restoreZeroReader struct{}

func (restoreZeroReader) Read(p []byte) (int, error) {
	clear(p)
	return len(p), nil
}
